    try {
      const created = await api(srv.url, 'POST', '/shipments', validShipment({ tracking_number: 'RR123456785AT' }));
      const id = created.body.id;
      const first = await api(srv.url, 'GET', '/shipments');
      const again = await api(srv.url, 'GET', '/shipments');
      assert.equal(first.body.items[0].eta, again.body.items[0].eta);

      // an exception adds business days: a stale cache would keep the old eta
      await api(srv.url, 'POST', `/shipments/${id}/events`, { type: 'exception' });
      const afterException = await api(srv.url, 'GET', '/shipments');
      const detail = await api(srv.url, 'GET', `/shipments/${id}`);
      assert.notEqual(afterException.body.items[0].eta, first.body.items[0].eta);
      assert.equal(afterException.body.items[0].eta, detail.body.eta);

      await api(srv.url, 'POST', `/shipments/${id}/events`, { type: 'delivered' });
      const delivered = await api(srv.url, 'GET', '/shipments');
      assert.equal(delivered.body.items[0].eta, null);
    } finally {
      await srv.close();
    }
  });
});
